#!/usr/bin/env python3
"""Screen / window / region capture for stream.sh (mode "screen").

Asks the desktop's screen-sharing portal (the same picker Discord gets:
screen, window or region on KDE), then GStreamer encodes the picture + all
sound of this computer into HLS in the given folder.
Prints STATUS:/ERROR: lines like stream.sh."""
# Part of VRChat Stream. Created by Lokinya (lokinyauv-create).
# Generated by AI (Claude, Anthropic). Apache-2.0.
import os
import subprocess
import sys
import time

import dbus
import dbus.mainloop.glib
import gi

gi.require_version("Gst", "1.0")
from gi.repository import GLib, Gst  # noqa: E402

# Settings from stream.sh (env vars, same names)
W, H, FPS, KBPS, AKBPS, SEG, LIST = (int(os.environ.get(k, d)) for k, d in (
    ("W", 1920), ("H", 1080), ("FPS", 30), ("KBPS", 4500), ("AKBPS", 160),
    ("SEG", 1), ("LIST", 4)))
SOURCE_MONITOR, SOURCE_WINDOW = 1, 2
CURSOR_HIDDEN, CURSOR_EMBEDDED = 1, 2
CURSOR = CURSOR_EMBEDDED if os.environ.get("CURSOR", "1") == "1" else CURSOR_HIDDEN
ENCODER = os.environ.get("ENCODER", "auto")

# GStreamer H.264 encoders for stream.sh's choice, best first
ENCODERS = {
    "nvenc": [f"nvh264enc bitrate={KBPS} rc-mode=cbr gop-size={FPS} bframes=0"],
    "vaapi": [f"vah264enc bitrate={KBPS} rate-control=cbr key-int-max={FPS} b-frames=0",
              f"vaapih264enc bitrate={KBPS} rate-control=cbr keyframe-period={FPS} max-bframes=0"],
    "x264": [f"x264enc bitrate={KBPS} tune=zerolatency speed-preset=veryfast key-int-max={FPS} bframes=0"],
    "openh264": [f"openh264enc bitrate={KBPS * 1000} gop-size={FPS} rate-control=bitrate"],
}

out_dir = sys.argv[1]
TEST = sys.argv[2:] == ["--test"]
dbus.mainloop.glib.DBusGMainLoop(set_as_default=True)
bus = dbus.SessionBus()
portal = bus.get_object("org.freedesktop.portal.Desktop", "/org/freedesktop/portal/desktop")
screencast = dbus.Interface(portal, "org.freedesktop.portal.ScreenCast")
sender = bus.get_unique_name()[1:].replace(".", "_")
loop = GLib.MainLoop()
session = None
pipeline = None
appsrc = None
segmenter = None
BLACK = None
token_n = 0
exit_code = 0


def say(line):
    print(line, flush=True)


def fail(msg):
    # Called from GLib/D-Bus callbacks, where exceptions are swallowed
    global exit_code
    say("ERROR: " + msg)
    exit_code = 1
    loop.quit()


def request(method, *args, then):
    """Call a portal method and run `then(results)` when its Response arrives."""
    global token_n
    token_n += 1
    token = f"vrchat{token_n}"
    path = f"/org/freedesktop/portal/desktop/request/{sender}/{token}"

    def on_response(code, results):
        if code != 0:
            fail("pick_cancelled" if code == 1 else f"portal_refused {code}")
        else:
            then(results)

    bus.add_signal_receiver(on_response, "Response", "org.freedesktop.portal.Request", None, path)
    options = args[-1]
    options["handle_token"] = token
    method(*args)


def create_session():
    request(screencast.CreateSession, {"session_handle_token": "vrchatsession"},
            then=select_sources)


def select_sources(results):
    global session
    session = results["session_handle"]
    say("STATUS: pick_on_server")
    request(screencast.SelectSources, session,
            {"types": dbus.UInt32(SOURCE_MONITOR | SOURCE_WINDOW),
             "multiple": False,
             "cursor_mode": dbus.UInt32(CURSOR)},
            then=start)


def start(_results):
    request(screencast.Start, session, "", {}, then=started)


def started(results):
    global node
    streams = results.get("streams", [])
    if not streams:
        return fail("portal_no_video")
    node = int(streams[0][0])
    if not TEST:
        bus.add_signal_receiver(lambda *_: fail("share_closed"),
                                "Closed", "org.freedesktop.portal.Session", None, session)
    Gst.init(None)
    if not start_output():
        return
    start_capture()
    GLib.timeout_add(1000 // FPS, push_frame)
    GLib.timeout_add_seconds(1, watchdog)
    say("STATUS: streaming")


# Two pipelines: "capture" takes whatever PipeWire gives (it may pause, change
# size or break when a window goes fullscreen) and only keeps the latest frame;
# "output" sends exactly FPS frames per second (repeating the last one), so the
# HLS stream never stalls and the capture side can be rebuilt on the fly.
node = None
capture = None
latest = None
last_frame_at = 0.0
rebuilds = 0


def black_frame():
    y, uv = bytes([16]) * (W * H), bytes([128]) * (W * H // 2)
    return Gst.Buffer.new_wrapped(y + uv)


def start_capture():
    global capture, last_frame_at
    if TEST:
        # --test: a source that ends after 3 s, to exercise the rebuild path
        src = "videotestsrc is-live=true pattern=ball num-buffers=90 ! video/x-raw,width=1280,height=720"
    else:
        fd = screencast.OpenPipeWireRemote(session, dbus.Dictionary({}, signature="sv")).take()
        src = f"pipewiresrc fd={fd} path={node} keepalive-time=500 always-copy=true"
    capture = Gst.parse_launch(
        f"{src}"
        f" ! videoconvert ! videoscale add-borders=true"
        f" ! video/x-raw,format=NV12,width={W},height={H},pixel-aspect-ratio=1/1"
        f" ! appsink name=sink emit-signals=true max-buffers=1 drop=true sync=false")
    capture.get_by_name("sink").connect("new-sample", on_sample)
    cbus = capture.get_bus()
    cbus.add_signal_watch()
    cbus.connect("message::error", lambda *_: GLib.idle_add(restart_capture))
    cbus.connect("message::eos", lambda *_: GLib.idle_add(restart_capture))
    last_frame_at = time.monotonic()
    capture.set_state(Gst.State.PLAYING)


def restart_capture():
    global capture, rebuilds
    rebuilds += 1
    if rebuilds > 10:
        fail("no_picture")
        return False
    old, capture = capture, None
    if old:
        old.set_state(Gst.State.NULL)
    start_capture()
    return False


def on_sample(sink):
    global latest, last_frame_at, rebuilds
    latest = sink.emit("pull-sample").get_buffer()
    last_frame_at = time.monotonic()
    rebuilds = 0
    return Gst.FlowReturn.OK


def watchdog():
    if capture and time.monotonic() - last_frame_at > 4:
        restart_capture()
    return True


def push_frame():
    # Fresh timestamps: captured frames carry the capture pipeline's own times,
    # which restart from zero after a rebuild
    buf = (latest or BLACK).copy()
    clock = pipeline.get_clock()
    if not clock:
        return True
    buf.pts = clock.get_time() - pipeline.get_base_time()
    buf.dts = Gst.CLOCK_TIME_NONE
    buf.duration = Gst.SECOND // FPS
    appsrc.emit("push-buffer", buf)
    return True


def encoder():
    order = [ENCODER] + [e for e in ENCODERS if e != ENCODER]
    for e in order:
        for desc in ENCODERS.get(e, []):
            if Gst.ElementFactory.find(desc.split()[0]):
                return desc
    return None


def start_output():
    global pipeline, appsrc, BLACK, segmenter
    BLACK = black_frame()
    enc = encoder()
    if not enc:
        fail("no_encoder")
        return False
    # ffmpeg cuts the muxed stream into HLS pieces, same as the browser mode
    read_fd, write_fd = os.pipe()
    segmenter = subprocess.Popen(
        ["ffmpeg", "-hide_banner", "-loglevel", "error", "-nostdin",
         "-f", "mpegts", "-i", f"pipe:{read_fd}", "-c", "copy",
         "-f", "hls", "-hls_time", str(SEG), "-hls_list_size", str(LIST),
         "-hls_flags", "delete_segments+omit_endlist+independent_segments",
         "-hls_segment_filename", f"{out_dir}/seg%05d.ts", f"{out_dir}/index.m3u8"],
        pass_fds=(read_fd,))
    os.close(read_fd)
    pipeline = Gst.parse_launch(
        f"appsrc name=src is-live=true format=time"
        f" caps=video/x-raw,format=NV12,width={W},height={H},framerate={FPS}/1,pixel-aspect-ratio=1/1"
        f" ! queue ! videoconvert ! {enc}"
        f" ! h264parse config-interval=-1 ! queue ! mux."
        f" pulsesrc device=@DEFAULT_MONITOR@ do-timestamp=true"
        f" ! queue ! audioconvert ! audioresample ! audio/x-raw,rate=48000,channels=2"
        f" ! avenc_aac bitrate={AKBPS * 1000} ! aacparse ! queue ! mux."
        f" mpegtsmux name=mux ! fdsink fd={write_fd} sync=false")
    appsrc = pipeline.get_by_name("src")
    pipeline.get_bus().add_signal_watch()
    pipeline.get_bus().connect("message::error", on_error)
    pipeline.set_state(Gst.State.PLAYING)
    return True


def on_error(_bus, msg):
    err, _dbg = msg.parse_error()
    fail(f"capture_stopped {err.message}")


GLib.idle_add(lambda: started({"streams": [(0, {})]}) if TEST else create_session())
try:
    loop.run()
finally:
    for p in (capture, pipeline):
        if p:
            p.set_state(Gst.State.NULL)
    if segmenter:
        segmenter.terminate()
sys.exit(exit_code)
